mapper.select:
SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId}
  AND turn_id = #{turnId}
  AND dispatch_attempt = #{dispatchAttempt}
  AND event_seq = #{eventSeq}
ORDER BY chunk_index ASC

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM agent_conversation_turn_event
WHERE gmt_create < #{cutoff}
LIMIT #{limit}
